using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace RetroWindows {static partial class ReferenceContent {
static readonly Dictionary<int,BitmapSource> pressedFaces=new Dictionary<int,BitmapSource>();
 public static BitmapSource PressedCalculator(int owner,int index){int key=owner*10+index;BitmapSource image;if(pressedFaces.TryGetValue(key,out image))return image;var rect=ReferenceMotion.CalculatorButton(owner,index);int w=(int)rect.Width,h=(int)rect.Height;using(var art=new Painter(owner==0))using(var b=new Bitmap(w*2,h*2,System.Drawing.Imaging.PixelFormat.Format32bppPArgb)){using(var g=Graphics.FromImage(b)){g.Clear(System.Drawing.Color.White);g.ScaleTransform(2,2);art.PressedControl(g,new[]{"C","1","9","8","4"}[index],w,h,owner==0?5:3);}var data=b.LockBits(new Rectangle(0,0,w*2,h*2),ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);try{var bytes=new byte[data.Stride*h*2];Marshal.Copy(data.Scan0,bytes,0,bytes.Length);for(int i=0;i<bytes.Length;i+=4){byte a=(byte)(255-bytes[i]);bytes[i]=bytes[i+1]=bytes[i+2]=0;bytes[i+3]=a;}image=BitmapSource.Create(w*2,h*2,192,192,PixelFormats.Pbgra32,null,bytes,data.Stride);image.Freeze();}finally{b.UnlockBits(data);}}pressedFaces[key]=image;return image;}
 sealed partial class Painter {public void PressedControl(Graphics g,string label,int width,int height,int pitch){Box(g,0,0,width,height,true);Label(g,label,8,8,width-12,height-12,pitch);}}
 public sealed class InteractionPatch {public System.Windows.Rect Bounds;public BitmapSource Image;}
 static readonly object interactionGate=new object();static int interactionOwner=-1;static readonly Dictionary<int,InteractionPatch> interactionImages=new Dictionary<int,InteractionPatch>();static bool interactionPreparing;
 public static int InteractionStates(int owner,int scene){if(scene==9||(owner==0&&scene==8))return 2;if(owner==1&&scene==20)return 3;if(owner==1&&(scene==15||scene==19))return 2;if(owner==1&&scene==18)return 7;if(owner==1&&scene==8)return 1;if(owner==0&&scene==20)return 3;if(owner==0&&scene==15)return 2;return 0;}
 static System.Windows.Rect InteractionBounds(int owner,int scene){if(owner==0&&scene==8)return new System.Windows.Rect(95,185,950,445);if(scene==9)return new System.Windows.Rect(70,195,1065,500);if(owner==1&&scene==19)return new System.Windows.Rect(70,65,1060,670);if(owner==1&&scene==15)return new System.Windows.Rect(90,190,1016,500);if(owner==1&&scene==18)return new System.Windows.Rect(98,577,1000,153);if(owner==1&&scene==20)return new System.Windows.Rect(98,200,1008,525);if(owner==1&&scene==8)return new System.Windows.Rect(75,190,1030,230);if(owner==0&&scene==15)return new System.Windows.Rect(205,300,910,420);return new System.Windows.Rect(86,270,940,410);}
 static InteractionPatch BuildInteraction(int owner,int scene,int state){var bounds=InteractionBounds(owner,scene);int w=(int)bounds.Width*2,h=(int)bounds.Height*2;BitmapSource image;using(var art=new Painter(owner==0){State=state})using(var b=new Bitmap(w,h,System.Drawing.Imaging.PixelFormat.Format32bppPArgb)){using(var g=Graphics.FromImage(b)){g.Clear(System.Drawing.Color.White);g.ScaleTransform(2,2);g.TranslateTransform(-(float)bounds.X,-(float)bounds.Y);art.Draw(g,scene);}var data=b.LockBits(new Rectangle(0,0,w,h),ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);try{var raw=new byte[data.Stride*h];Marshal.Copy(data.Scan0,raw,0,raw.Length);for(int i=0;i<raw.Length;i+=4){byte a=(byte)(255-raw[i]);raw[i]=raw[i+1]=raw[i+2]=0;raw[i+3]=a;}image=BitmapSource.Create(w,h,192,192,PixelFormats.Pbgra32,null,raw,data.Stride);image.Freeze();image=Macintosh.FluidView.BakeInk(image);}finally{b.UnlockBits(data);}}return new InteractionPatch{Bounds=bounds,Image=image};}
 public static void PrepareInteraction(int owner,int scene){int key=owner*100+scene,count=InteractionStates(owner,scene);lock(interactionGate){if(key!=interactionOwner){interactionOwner=key;interactionImages.Clear();interactionPreparing=false;}if(count==0||interactionPreparing||interactionImages.Count==count)return;interactionPreparing=true;}
 System.Threading.ThreadPool.QueueUserWorkItem(delegate{try{for(int state=1;state<=count;state++){var patch=BuildInteraction(owner,scene,state);lock(interactionGate){if(interactionOwner!=key)return;interactionImages[state]=patch;}}}finally{lock(interactionGate){if(interactionOwner==key)interactionPreparing=false;}}});}
 public static InteractionPatch Interaction(int owner,int scene,int state,bool synchronous){if(state==0)return null;int key=owner*100+scene;lock(interactionGate){if(interactionOwner==key){InteractionPatch value;if(interactionImages.TryGetValue(state,out value))return value;}}if(!synchronous)return null;var built=BuildInteraction(owner,scene,state);lock(interactionGate){if(interactionOwner!=key){interactionOwner=key;interactionImages.Clear();}interactionImages[state]=built;}return built;}
}}
